import "server-only";
import path from "node:path";
import { drizzle } from "drizzle-orm/node-postgres";
import { migrate } from "drizzle-orm/node-postgres/migrator";
import { getPool } from "./client";
import * as schema from "./schema";

/**
 * Applies pending SQL migrations from drizzle/ (generated by `npx drizzle-kit generate`,
 * committed). Runs on every boot (lib/server/bootstrap.ts); already-applied migrations
 * are skipped via drizzle's journal table (drizzle.__drizzle_migrations).
 *
 * A Postgres advisory lock serializes concurrent boots (e.g. a rolling restart that
 * briefly runs two containers), so a migration is never applied twice in parallel.
 */

/** Arbitrary constant: "NQ" + "MIGR" as bytes, shared by every NUSAQUEST instance. */
const MIGRATION_LOCK_KEY = 0x4e51_4d49;

export function migrationsFolder(): string {
  return path.join(process.cwd(), "drizzle");
}

export async function runMigrations(): Promise<void> {
  const pool = getPool();
  if (!pool) return;
  const client = await pool.connect();
  try {
    await client.query("select pg_advisory_lock($1)", [MIGRATION_LOCK_KEY]);
    try {
      await migrate(drizzle(client, { schema }), { migrationsFolder: migrationsFolder() });
    } finally {
      await client.query("select pg_advisory_unlock($1)", [MIGRATION_LOCK_KEY]);
    }
  } finally {
    client.release();
  }
}
